INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p509711-om310', 'stk-kfupm_man', 'OM 310', 'info', '{"desc": "الماده ماهي بالصعوه القويه لكنها دسمه واذا كان مالك فالرياضيات او الاحصاء فلاتأخذها (الا اذا كنت مجبر)\nالدكتور طيب ومتفهم لكن مواعيده فيها مشكله كبيرة\nيعني الكورس اخذته كان الساعه 6 لأن الرجل يعطي للماجستير بعد مايعطي لطلاب البكالريوس\nالمدرس يعطيط افضل درجه بين الاختبار الفاينل والميدتسرم ويعتبر الاثنين بنفس درجه الاعلى\nلكن يبغالك شغل وتركيز\nالكاده فيها برسينتيشن صغير\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/om310/81291/3", "user": "kfupm_man", "ts": 1261898861000, "tid": 81291, "pn": 3}}', 1261898861000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p742352-om310', 'stk-cartman', 'OM 310', 'info', '{"desc": "الماده مااعرف عنها شي\nبس الدكتور فاهم وشرّيح وأسألته على قد شرحه\nيعني صعبه\nراح تستفيد تمام بس اذا تبغى نصيحتي\n\nبما انك طالب ماركتينق … وال OM 310 تستناك 😁 فنزلها السمستر هذا\nسكشن واحد في نفس توقيت ال425\n\nلأن في العاده تنزل مع تقي الفرج … واسألة صعبه ويعقد الدنيا\nبينما السمستر هذا من باب التغيير منزلها الزاير … وزي منت عارف ان الوضع معاه سهاله وأسهل بكثير من الفرج\n\nففرصه تنزل الكورس السمستر الجاي … ولاحق ع الإليكتف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mkt-mgt/81186/78", "user": "cartman", "ts": 1292142708000, "tid": 81186, "pn": 78}}', 1292142708000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
